widgets_sidebar.css:
.sidebar .widget {
  background: #ffffff;
  padding: 1.5rem;
  border-radius: 12px;
  border: 1px solid var(--el-border);
  margin-bottom: 2rem;
}
.widget h2.title {
  font-size: 1rem;
  font-weight: 700;
  color: var(--el-text);
  border-bottom: 2px solid var(--el-primary);
  padding-bottom: 0.5rem;
  margin-bottom: 1rem;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

scrollbar_customizada.css:
::-webkit-scrollbar { width: 8px; }
::-webkit-scrollbar-track { background: var(--el-bg); }
::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 10px; }
::-webkit-scrollbar-thumb:hover { background: var(--el-primary); }

footer.css:
.site-footer { background-color: var(--el-footer); color: #94a3b8; }
.site-footer a { color: #e2e8f0; }
.site-footer a:hover { color: #ffffff; text-decoration: underline; }
